-- Generated by tools/write_source_queries.py from focus/data/datasets.py. Read-only; explicit projection (S05).
-- Complete broad WIP/anchor census: all statuses (including COMPLETE anchors) on every line with any non-COMPLETE work.
WITH WipLines AS (
 SELECT DISTINCT LINE_NUMBER FROM WEB_APP.FOCUS_MASTER_TASK_LIST
 WHERE SHOP_ORDER_STATUS <> 'COMPLETE'
)
SELECT m.SHOP_ORDER_IDENTIFIER,m.SHOP_ORDER_DESCRIPTION,m.LINE_NUMBER,m.SHOP_ORDER_STATUS,m.TEAM,m.CURRENT_CONTROL_STATION,m.MINOR_MODEL_IDENT,m.CUSTOMER_CODE,m.PARENT_SOI,m.SUPERINTENDENT,m.FIRST_AVAILABLE,m.ACT_START,m.ACT_COMP,m.LOAD_TIMESTAMP,m.PLANNING_SYSTEM_NAME,m.IS_REWORK,m.RECORD_KEY
FROM WEB_APP.FOCUS_MASTER_TASK_LIST m
JOIN WipLines w ON w.LINE_NUMBER=m.LINE_NUMBER
ORDER BY m.LINE_NUMBER,m.SHOP_ORDER_IDENTIFIER;
